-- One student, never another's rows (RLS pgTAP plan, D3 O1 to O13 and V1). For every owner-read
-- table: account A reads exactly its own rows and none of B's, and writes nothing at all, its own
-- rows included; B reads exactly its own rows; a session with no `sub`, or with a `sub` no account
-- has, reads nothing. V1: the one invoker view shows A its own subscriber row only.
--
-- Every case is generated by a loop over `tests.matrix` (`access = 'own'`), so a new owner-read
-- table needs only its matrix row and its fixture case. Each probe is one driver call, the
-- expression `09_self_test_test.sql` showed failing against its own planted fault on
-- `public.issues`: `tests.probe` for a read or an insert, `tests.probe_write` for an upsert, an
-- update or a delete. Every assertion runs as the owner; only the probe runs as the client.
--
-- What each case expects (D3):
-- - O1, O11: the reader's count equals the owner's count of that account's rows, and none of the
--   rows it sees is keyed to another account.
-- - O2, O12, O13: 0.
-- - O3, O4: -2, an RLS refusal. The insert is the fixture's own valid row (`tests.insert_sql`) into
--   the account's cleared slot (`tests.clear_sql`), so only a grant or a policy can refuse it.
-- - O5: `(-2,f)`, B's own row upserted onto B's existing primary key, and B's rows unchanged.
-- - O6 to O10: `(0,f)`, nothing touched and the owner's re-read unchanged (ctid, key, sentinel).
-- A read case whose fixture rows are missing fails by name; it never passes on an empty table.
--
-- No id is printed: ids are read from `tests.accounts` as the owner and spliced into the probe text
-- as `%L` literals, and every description names a case and a relation only.
begin;
\ir _setup.psql
\ir _matrix.psql
\ir _fixtures.psql

-- The sync triggers (progress.md, the T5b ruling and its correction; T6b and T7 reviews).
-- `sync_records_usage` and `sync_notes_usage` run `sync_usage_bump`, which is SECURITY INVOKER and
-- upserts the account's `sync_usage` row. If a client's insert or update on `sync_records` or
-- `sync_notes` got past that table's own policy (a real hole), the trigger's upsert would run as
-- the client, `sync_usage`'s RLS would refuse it, and the probe would read -2, or `(-2,f)`: the
-- value a refusal gives, so the hole would be masked. So every insert, upsert and update probe
-- runs through `_setup.psql`'s `tests.unmasked`, which disables the table's
-- `tests.unmask_triggers` (non-internal, row-level, AFTER, on INSERT or UPDATE; none on most
-- tables) by owner DDL inside `tests.under_fault`, rolled back with the probe, so the probe sees
-- the table's own policy and nothing else. Disabling an after trigger can only remove an error
-- raised once a row has passed RLS: it can unmask a hole, never make a refused write look
-- accepted. Delete probes call the driver directly and keep the triggers on: on DELETE the
-- function runs a plain `update`, which RLS filters to 0 rows, so it hides no delete hole.
-- `sync_notes_rev_stamp` is BEFORE, so it stays on everywhere; it only stamps `rev` and
-- `updated_at`, and C9 (01) pins it as `tests.stamp_only`. 09 shows the mask is real and the
-- unmask lifts it, for A inserting B's row into each sync table; C9 fails on any other trigger.

-- A check's value as text: through `tests.unmasked` when `p_unmask`, run directly otherwise.
-- Either way the check is the same driver call.
create function tests.own_value(p_unmask boolean, p_rel text, p_check text) returns text
language plpgsql as $$
declare v text;
begin
  if p_unmask then
    return tests.unmasked(p_rel, p_check);
  end if;
  execute format('select (%s)::text', p_check) into v;
  return v;
end $$;

-- A write probe as A, with the owner's re-read of `p_target` (D5's `tests.probe_write`), as text:
-- `(n,changed)`.
create function tests.own_write(p_unmask boolean, p_rel text, p_sql text, p_target text)
returns text language plpgsql as $$
begin
  return tests.own_value(p_unmask, p_rel, format('tests.probe_write(%L, %L, %L, %L)::text',
    'A', p_rel, p_sql, p_target));
end $$;

-- D3's per-type sentinel for the table's `touch_col`, as an SQL expression: 'rls-probe' for text,
-- -424242 for numbers, a year ago for dates and times, `not <col>` for booleans. Any other type
-- raises, so a matrix row that names one fails loud.
create function tests.own_sentinel(p_rel text) returns text language plpgsql as $$
declare v_col text; v_cat text;
begin
  select m.touch_col, t.typcategory::text into strict v_col, v_cat
    from tests.matrix m
    join pg_attribute a on a.attrelid = m.rel::regclass and a.attname = m.touch_col
    join pg_type t on t.oid = a.atttypid
   where m.rel = p_rel and m.kind = 'table' and not a.attisdropped;
  case v_cat
    when 'S' then return quote_literal('rls-probe');
    when 'N' then return '-424242';
    when 'D' then return $s$now() - interval '1 year'$s$;
    when 'B' then return format('not %I', v_col);
    else raise exception 'tests.own_sentinel: no sentinel for % (type category %)', p_rel, v_cat;
  end case;
end $$;

-- O5's statement: B's own row, read as the owner, inserted back onto B's existing primary key with
-- `on conflict (<primary key>) do update set <touch_col> = excluded.<touch_col>`. Every column a
-- statement may write is listed (a generated one may not be), each value a typed literal that
-- round-trips through its text form, with `overriding system value` when the table has an
-- always-identity column. So the row passes every check and the conflict is certain: only a policy
-- can refuse it, and the insert's own WITH CHECK refuses it before the conflict is looked for.
-- B's row must exist (`into strict`), so an empty slot raises rather than test nothing.
create function tests.own_upsert_sql(p_rel text) returns text language plpgsql as $$
declare
  v_where text := tests.slot_where(p_rel, 'B');
  v_touch text;
  v_pk text;
  v_cols text[] := '{}';
  v_vals text[] := '{}';
  v_over text := '';
  v text;
  r record;
begin
  select m.touch_col into strict v_touch
    from tests.matrix m where m.rel = p_rel and m.kind = 'table';
  select string_agg(format('%I', a.attname), ', ' order by k.ord) into v_pk
    from pg_index i
    cross join lateral unnest(i.indkey) with ordinality as k(attnum, ord)
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
   where i.indrelid = p_rel::regclass and i.indisprimary;
  if v_pk is null then
    raise exception 'tests.own_upsert_sql: % has no primary key', p_rel;
  end if;
  for r in
    select a.attname, format_type(a.atttypid, a.atttypmod) as typ, a.attidentity::text as ident
      from pg_attribute a
     where a.attrelid = p_rel::regclass and a.attnum > 0 and not a.attisdropped
       and a.attgenerated = ''
     order by a.attnum
  loop
    -- `p_rel` is a matrix name (pattern-checked), so it is spliced as written.
    execute format('select %I::text from %s where %s order by %s limit 1',
      r.attname, p_rel, v_where, v_pk) into strict v;
    v_cols := v_cols || format('%I', r.attname);
    v_vals := v_vals || case when v is null then format('null::%s', r.typ)
                             else format('%L::%s', v, r.typ) end;
    if r.ident = 'a' then
      v_over := ' overriding system value';
    end if;
  end loop;
  return format('insert into %s (%s)%s values (%s) on conflict (%s) do update set %I = excluded.%I',
    p_rel, array_to_string(v_cols, ', '), v_over, array_to_string(v_vals, ', '), v_pk,
    v_touch, v_touch);
end $$;

-- O1 to O13 for one owner-read table after another, in a fixed order, 13 cases each. Each case's
-- value is read first and asserted as the owner. The read cases compare with the owner's counts of
-- the same slots (`tests.slot_where`), so a fixture with no row for the account fails by name.
create function tests.own_rows_cases() returns setof text language plpgsql as $$
declare
  r record;
  v_a uuid;
  v_b uuid;
  v_sent text;
  v_slot_a text;
  v_slot_b text;
  n_a bigint;
  n_b bigint;
  n_all bigint;
  v_seen bigint;
  v_else bigint;
begin
  select a.id into strict v_a from tests.accounts a where a.who = 'A';
  select a.id into strict v_b from tests.accounts a where a.who = 'B';
  for r in
    select m.rel, m.key_col, m.touch_col
      from tests.matrix m
     where m.access = 'own'
     order by m.rel
  loop
    -- The insert, upsert and update probes run through `tests.unmasked` (`true` below; see the
    -- comment above `tests.own_value` for why), the delete probes directly (`false`).
    v_sent := tests.own_sentinel(r.rel);
    v_slot_a := tests.slot_where(r.rel, 'A');
    v_slot_b := tests.slot_where(r.rel, 'B');
    execute format('select count(*) from %s where %s', r.rel, v_slot_a) into n_a;
    execute format('select count(*) from %s where %s', r.rel, v_slot_b) into n_b;
    execute format('select count(*) from %s', r.rel) into n_all;

    -- O1: A sees exactly as many rows as A owns, and none of them is keyed to anyone else.
    v_seen := tests.probe('A', format('select count(*) from %s', r.rel));
    v_else := tests.probe('A', format('select count(*) from %s where %I is distinct from %L',
      r.rel, r.key_col, v_a));
    return next is(format('%s seen, %s keyed elsewhere', v_seen, v_else),
      case when n_a > 0 then format('%s seen, 0 keyed elsewhere', n_a)
           else 'a fixture row for A to see' end,
      format('O1: A reads exactly its own rows of %s, every one keyed to A', r.rel));

    -- O2: B's rows, asked for by B's key.
    v_seen := tests.probe('A', format('select count(*) from %s where %s', r.rel, v_slot_b));
    return next is(v_seen::text,
      case when n_b > 0 then '0' else 'a fixture row for B to hide' end,
      format('O2: A reads none of B''s rows of %s by their key', r.rel));

    -- O3 and O4: the fixture's own valid row, into the account's cleared slot.
    return next is(
      tests.own_value(true, r.rel, format('tests.probe(%L, %L, %L)', 'A',
        tests.insert_sql(r.rel, 'A'), tests.clear_sql(r.rel, 'A'))),
      '-2', format('O3: A''s insert of a row for A into %s is an RLS refusal (-2)', r.rel));
    return next is(
      tests.own_value(true, r.rel, format('tests.probe(%L, %L, %L)', 'A',
        tests.insert_sql(r.rel, 'B'), tests.clear_sql(r.rel, 'B'))),
      '-2', format('O4: A''s insert of a row for B into %s is an RLS refusal (-2)', r.rel));

    -- O5: B's own row upserted onto B's existing primary key; the re-read is B's slot.
    return next is(tests.own_write(true, r.rel, tests.own_upsert_sql(r.rel), v_slot_b),
      '(-2,f)',
      format('O5: A''s upsert onto B''s key in %s is an RLS refusal, B''s rows unchanged', r.rel));

    -- O6 and O7: `touch_col` set to its sentinel on A's rows, then on B's.
    return next is(tests.own_write(true, r.rel,
        format('update %s set %I = %s where %s', r.rel, r.touch_col, v_sent, v_slot_a), v_slot_a),
      '(0,f)', format('O6: A''s update of its own rows of %s touches nothing', r.rel));
    return next is(tests.own_write(true, r.rel,
        format('update %s set %I = %s where %s', r.rel, r.touch_col, v_sent, v_slot_b), v_slot_b),
      '(0,f)', format('O7: A''s update of B''s rows of %s touches nothing', r.rel));

    -- O8: the move, A's rows re-keyed to B; the re-read is A's slot, so a row that left reads as
    -- changed.
    return next is(tests.own_write(true, r.rel,
        format('update %s set %I = %L where %s', r.rel, r.key_col, v_b, v_slot_a), v_slot_a),
      '(0,f)', format('O8: A''s move of its own rows of %s to B touches nothing', r.rel));

    -- O9 and O10: deletes, with no owner DDL: the triggers stay on, since they mask no delete hole.
    return next is(tests.own_write(false, r.rel,
        format('delete from %s where %s', r.rel, v_slot_a), v_slot_a),
      '(0,f)', format('O9: A''s delete of its own rows of %s touches nothing', r.rel));
    return next is(tests.own_write(false, r.rel,
        format('delete from %s where %s', r.rel, v_slot_b), v_slot_b),
      '(0,f)', format('O10: A''s delete of B''s rows of %s touches nothing', r.rel));

    -- O11: the mirror of O1, for B.
    v_seen := tests.probe('B', format('select count(*) from %s', r.rel));
    v_else := tests.probe('B', format('select count(*) from %s where %I is distinct from %L',
      r.rel, r.key_col, v_b));
    return next is(format('%s seen, %s keyed elsewhere', v_seen, v_else),
      case when n_b > 0 then format('%s seen, 0 keyed elsewhere', n_b)
           else 'a fixture row for B to see' end,
      format('O11: B reads exactly its own rows of %s, every one keyed to B', r.rel));

    -- O12 and O13: an authenticated session with no `sub`, and one whose `sub` is fresh and random
    -- (the driver's `stranger`, a new `gen_random_uuid()` on every call), over the whole table.
    v_seen := tests.probe('nosub', format('select count(*) from %s', r.rel));
    return next is(v_seen::text,
      case when n_all > 0 then '0' else 'fixture rows to hide' end,
      format('O12: a session with no sub reads no row of %s', r.rel));
    v_seen := tests.probe('stranger', format('select count(*) from %s', r.rel));
    return next is(v_seen::text,
      case when n_all > 0 then '0' else 'fixture rows to hide' end,
      format('O13: a sub with no account reads no row of %s', r.rel));
  end loop;
end $$;

-- V1: `billing_subscribers` is `security_invoker`, so A reads it through the policies of
-- `accounts`, `entitlements` and `billing_reminders`. A and B both hold an active subscription in
-- the fixture, so the view has a row for each as the owner; A must see its own and not B's.
create function tests.own_v1() returns text language plpgsql as $$
declare
  v_a uuid;
  v_b uuid;
  n_a bigint;
  n_b bigint;
  v_seen bigint;
  v_else bigint;
begin
  select a.id into strict v_a from tests.accounts a where a.who = 'A';
  select a.id into strict v_b from tests.accounts a where a.who = 'B';
  select count(*) filter (where s.account_id = v_a), count(*) filter (where s.account_id = v_b)
    into n_a, n_b
    from public.billing_subscribers s;
  v_seen := tests.probe('A', 'select count(*) from public.billing_subscribers');
  v_else := tests.probe('A', format(
    'select count(*) from public.billing_subscribers where account_id is distinct from %L', v_a));
  return is(format('%s seen, %s keyed elsewhere', v_seen, v_else),
    case when n_a > 0 and n_b > 0 then format('%s seen, 0 keyed elsewhere', n_a)
         else 'an active subscription for A and for B in the fixture' end,
    'V1: A reads exactly its own row of public.billing_subscribers, though B holds one too');
end $$;

-- One guard, 13 cases for every owner-read table, plus V1.
select plan(1 + 13 * (select count(*)::int from tests.matrix m where m.access = 'own') + 1);

-- Counts and names only: what the plan above was computed from, and which triggers the insert,
-- upsert and update probes run without.
select diag(format('owner-read tables: %s, 13 cases each, plus V1', count(*)))
  from tests.matrix m
 where m.access = 'own';
select diag('insert, upsert and update probes run with these after triggers disabled: '
  || coalesce(string_agg(m.rel || ' ' || tests.unmask_triggers(m.rel)::text, ', '
       order by m.rel), 'none'))
  from tests.matrix m
 where m.access = 'own' and cardinality(tests.unmask_triggers(m.rel)) > 0;

-- A loop over nothing passes; this case fails if the matrix lists no owner-read table.
select ok((select count(*) from tests.matrix m where m.access = 'own') > 0,
  'O guard: the matrix lists owner-read tables to probe');

select * from tests.own_rows_cases();
select tests.own_v1();

select * from finish();
rollback;
